  if (data) payrollEmailExportSnapshot = {
    data: JSON.parse(JSON.stringify(data)),
    variant: variant === "compact" ? "compact" : "detail",
    pagination: pagination === "paginate" ? "paginate" : "fit-one-page",
  };

