      var pcts=groups.map(function(group){var field=group.querySelector('.detail-role-pct-input');return field ? window.TipOutEmployeeWeights.parse(field.value) : 0;});
      var totalPct=pcts.reduce(function(sum,pct){return sum+pct;},0);
      var cents=Math.round(Number(card.getAttribute('data-pool'))*totalPct);
      var budgets=window.TipOutEmployeeWeights.split(cents,pcts);
