    function collectSalesConditions() {
      var cond = {};
      var container = document.getElementById('salesConditionsContainer');
      if (!container) return cond;
      container.querySelectorAll('.condition-card').forEach(function(card) {
        var id = card.id || '';
        var type = id.replace('sales-cond-', '');
        if (!type) return;
        if (type === 'role') {
          var roleMs = card.querySelector('.role-role-select');
          if (roleMs) {
            var checked = roleMs.querySelectorAll('input[type="checkbox"]:checked');
            cond.role = Array.from(checked).map(function(c) { return c.value; });
          }
        } else if (type === 'employee') {
          var ecRoleMs = card.querySelector('.employee-condition-role-select');
          var ecStaffMs = card.querySelector('.employee-condition-staff-select');
          if (ecRoleMs) {
            cond.employeeRoles = Array.from(ecRoleMs.querySelectorAll('input[type="checkbox"]:checked')).map(function(c) { return c.value; });
          }
          if (ecStaffMs) {
            cond.employee = Array.from(ecStaffMs.querySelectorAll('input[type="checkbox"]:not(.role-employee-select-all-cb):checked')).map(function(c) { return c.value; });
          }
        } else if (type === 'area' || type === 'orderType' || type === 'revenueType' || type === 'orderTipStatus') {
          var sel = card.querySelector('select');
          if (sel) {
            var v = sel.value || '';
            if (type === 'orderTipStatus') {
              if (v === 'has_tip' || v === 'no_tip') cond.orderTipStatus = v;
            } else {
              cond[type] = v;
            }
          }
        } else if (type === 'paymentMethods') {
          var pm = collectPaymentMethodsFromCard(card);
          if (pm.length) cond.paymentMethods = pm;
        } else if (type === 'menu') {
          var menuObjSales = collectMenuCascadeObject(card);
          if (menuObjSales) cond.menu = menuObjSales;
        } else if (type === 'hours') {
          var inputs = card.querySelectorAll('input[type="time"]');
          cond.hours = { start: inputs[0] ? inputs[0].value : '', end: inputs[1] ? inputs[1].value : '' };
        } else if (type === 'shift') {
          var shiftMs = card.querySelector('.shift-condition-select');
          if (shiftMs) {
            var checked = shiftMs.querySelectorAll('input[type="checkbox"]:checked');
            cond.shift = Array.from(checked).map(function(c) { return c.value; });
          }
        } else if (type === 'weekday') {
          var wMs = card.querySelector('.weekday-condition-select');
          if (wMs) {
            var wChecked = wMs.querySelectorAll('input[type="checkbox"]:checked');
            cond.weekdays = Array.from(wChecked).map(function(c) { return c.value; });
          }
        }
      });
      return cond;
    }
